// Small bounded interpreter for precisely the emitted x86 instructions. It
// executes production-generated bytes against memory/API contracts; it neither
// starts processes nor calls native APIs. Unknown instructions fail the test.
type cpu270 struct {
	r     [8]uint32 // EAX ECX EDX EBX ESP EBP ESI EDI
	ip    uint32
	mem   map[uint32]byte
	z     bool
	api   map[uint32]func(*cpu270)
	steps int
	stop  uint32
}

func (c *cpu270) put(a uint32, b []byte) {
	for i, v := range b {
		c.mem[a+uint32(i)] = v
	}
}
func (c *cpu270) byte() byte  { v := c.mem[c.ip]; c.ip++; return v }
func (c *cpu270) u16() uint16 { return uint16(c.byte()) | uint16(c.byte())<<8 }
func (c *cpu270) u32() uint32 { return uint32(c.u16()) | uint32(c.u16())<<16 }
func (c *cpu270) read(a uint32) uint32 {
	return uint32(c.mem[a]) | uint32(c.mem[a+1])<<8 | uint32(c.mem[a+2])<<16 | uint32(c.mem[a+3])<<24
}
func (c *cpu270) write(a, v uint32) { c.put(a, binary.LittleEndian.AppendUint32(nil, v)) }
func (c *cpu270) push(v uint32)     { c.r[4] -= 4; c.write(c.r[4], v) }
func (c *cpu270) pop() uint32       { v := c.read(c.r[4]); c.r[4] += 4; return v }
func (c *cpu270) operand(m byte) (int, uint32) {
	mode, rm := m>>6, int(m&7)
	if mode == 3 {
		return rm, 0
	}
	var a uint32
	if rm == 4 {
		sib := c.byte()
		if sib != 0x24 {
			panic("unsupported SIB")
		}
		a = c.r[4]
	} else if mode == 0 && rm == 5 {
		a = c.u32()
	} else {
		a = c.r[rm]
	}
	switch mode {
	case 1:
		a += uint32(int32(int8(c.byte())))
	case 2:
		a += c.u32()
	}
	return -1, a
}
func (c *cpu270) get(r int, a uint32) uint32 {
	if r >= 0 {
		return c.r[r]
	}
	return c.read(a)
}
func (c *cpu270) set(r int, a, v uint32) {
	if r >= 0 {
		c.r[r] = v
	} else {
		c.write(a, v)
	}
}
func (c *cpu270) ret(n uint32) {
	c.ip = c.pop()
	c.r[4] += n
	if c.ip == c.stop {
		c.ip = 0xdeadbeef
	}
}
func (c *cpu270) run(t *testing.T) {
	t.Helper()
	for c.ip != 0xdeadbeef {
		c.steps++
		if c.steps > 10000 {
			t.Fatal("bounded execution exceeded")
		}
		op := c.byte()
		switch {
		case op >= 0x50 && op <= 0x57:
			c.push(c.r[op-0x50])
		case op >= 0x58 && op <= 0x5f:
			c.r[op-0x58] = c.pop()
		case op >= 0xb8 && op <= 0xbf:
			c.r[op-0xb8] = c.u32()
		case op == 0x68:
			c.push(c.u32())
		case op == 0x55:
			c.push(c.r[5])
		case op == 0x8b || op == 0x89 || op == 0x8d:
			m := c.byte()
			r, a := c.operand(m)
			reg := int(m >> 3 & 7)
			if op == 0x8b {
				c.r[reg] = c.get(r, a)
			} else if op == 0x89 {
				c.set(r, a, c.r[reg])
			} else {
				if r >= 0 {
					t.Fatal("invalid LEA")
				}
				c.r[reg] = a
			}
		case op == 0x85:
			m := c.byte()
			r, a := c.operand(m)
			c.z = c.get(r, a)&c.r[m>>3&7] == 0
		case op == 0x81 || op == 0x83:
			m := c.byte()
			r, a := c.operand(m)
			v := uint32(0)
			if op == 0x81 {
				v = c.u32()
			} else {
				v = uint32(int32(int8(c.byte())))
			}
			switch m >> 3 & 7 {
			case 7:
				c.z = c.get(r, a) == v
			case 5:
				c.set(r, a, c.get(r, a)-v)
			default:
				t.Fatalf("unsupported immediate %x", m)
			}
		case op == 0xc7:
			m := c.byte()
			r, a := c.operand(m)
			c.set(r, a, c.u32())
		case op == 0x66:
			if c.byte() != 0x81 {
				t.Fatal("unknown word operation")
			}
			m := c.byte()
			r, a := c.operand(m)
			if r >= 0 || m>>3&7 != 7 {
				t.Fatal("unknown word compare")
			}
			v := c.u16()
			c.z = uint16(c.mem[a])|uint16(c.mem[a+1])<<8 == v
		case op == 0x0f:
			cond := c.byte()
			disp := c.u32()
			if cond != 0x84 && cond != 0x85 {
				t.Fatal("unknown condition")
			}
			if cond == 0x84 && c.z || cond == 0x85 && !c.z {
				c.ip += disp
			}
		case op == 0xe9:
			disp := c.u32()
			c.ip += disp
		case op == 0xff:
			m := c.byte()
			r, a := c.operand(m)
			v := c.get(r, a)
			switch m >> 3 & 7 {
			case 6:
				c.push(v)
			case 2:
				fn := c.api[v]
				if fn == nil {
					t.Fatalf("unknown native call %x", v)
				}
				c.push(c.ip)
				fn(c)
			case 4:
				fn := c.api[v]
				if fn == nil {
					t.Fatalf("unknown native jump %x", v)
				}
				fn(c)
			default:
				t.Fatal("unknown FF")
			}
		case op == 0xc2:
			c.ret(uint32(c.u16()))
		default:
			t.Fatalf("unknown opcode %02x at %x", op, c.ip-1)
		}
	}
}
func cpu270Start(code []byte, args []uint32, ret uint32) *cpu270 {
	c := &cpu270{mem: map[uint32]byte{}, api: map[uint32]func(*cpu270){}, ip: 0x10000, stop: ret}
	c.r = [8]uint32{0x11, 0x22, 0x33, 0x4444, 0x800000, 0x5555, 0x6666, 0x7777}
	c.put(c.ip, code)
	for i := len(args) - 1; i >= 0; i-- {
		c.push(args[i])
	}
	c.push(ret)
	return c
}

func TestMulti270MutexMachineCode(t *testing.T) {
	for _, tc := range []struct {
		name     string
		caller   uint32
		key      string
		redirect bool
	}{{"target", multi270Base + multi270MutexReturn, multi270Key, true}, {"othercaller", 0xdeadbeef, multi270Key, false}, {"otherkey", multi270Base + multi270MutexReturn, "other", false}, {"suffix", multi270Base + multi270MutexReturn, multi270Key + "x", false}} {
		t.Run(tc.name, func(t *testing.T) {
			code, err := multi270MutexThunk(0x90000, 0xa0000)
			if err != nil {
				t.Fatal(err)
			}
			c := cpu270Start(code, []uint32{0, 1, 0xb0000}, tc.caller)
			c.put(0xb0000, multi270Wide(tc.key))
			gle := uint32(77)
			calls := 0
			c.api[0x90000] = func(c *cpu270) {
				calls++
				p := c.read(c.r[4] + 12)
				want := uint32(0xb0000)
				if tc.redirect {
					want = 0xa0000
				}
				if p != want || c.read(c.r[4]+4) != 0 || c.read(c.r[4]+8) != 1 {
					t.Fatal("altered non-name parameter")
				}
				c.r[0] = 0xcafe
				gle = 183
				c.ret(12)
				c.ip = 0xdeadbeef
			}
			c.run(t)
			if calls != 1 || c.r[0] != 0xcafe || gle != 183 || c.r[3] != 0x4444 || c.r[5] != 0x5555 || c.r[6] != 0x6666 || c.r[7] != 0x7777 {
				t.Fatal("original handle/GLE/register contract changed")
			}
		})
	}
}

func TestMulti270WindowMachineCode(t *testing.T) {
	api := multi270APIs{0x90000, 0x90010, 0x90020, 0x90030, 0x90040, 0x90050, 0x90060}
	const firstPID = 123
	const firstBirth = uint64(0x1122334455667788)
	for _, tc := range []struct {
		name, class              string
		caller                   uint32
		title                    uint32
		owner                    uint32
		birth                    uint64
		openOK, timesOK, closeOK bool
		hide                     bool
	}{
		{"chinese", multi270Classes[0], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, true, true, true, true},
		{"korean", multi270Classes[1], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, true, true, true, true},
		{"foreign", multi270Classes[0], multi270Base + multi270WindowReturn, 0, 124, firstBirth, true, true, true, false},
		{"reusedPID", multi270Classes[0], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth + 1, true, true, true, false},
		{"openunknown", multi270Classes[0], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, false, true, true, false},
		{"birthunknown", multi270Classes[0], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, true, false, true, false},
		{"closeunknown", multi270Classes[0], multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, true, true, false, false},
		{"othercaller", multi270Classes[0], 0xdeadbeef, 0, firstPID, firstBirth, true, true, true, false},
		{"othertitle", multi270Classes[0], multi270Base + multi270WindowReturn, 1, firstPID, firstBirth, true, true, true, false},
		{"otherclass", "other", multi270Base + multi270WindowReturn, 0, firstPID, firstBirth, true, true, true, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			code, err := multi270WindowThunk(api, firstPID, firstBirth)
			if err != nil {
				t.Fatal(err)
			}
			c := cpu270Start(code, []uint32{0xb0000, tc.title}, tc.caller)
			c.put(0xb0000, multi270Wide(tc.class))
			gle := uint32(91)
			findCalls, openCalls, closeCalls := 0, 0, 0
			c.api[api.FindWindow] = func(c *cpu270) {
				findCalls++
				if c.read(c.r[4]+4) != 0xb0000 || c.read(c.r[4]+8) != tc.title {
					t.Fatal("FindWindow original args changed")
				}
				c.r[0] = 0xabcd
				gle = 92
				c.ret(8)
			}
			c.api[api.GetLastError] = func(c *cpu270) { c.r[0] = gle; c.ret(0) }
			c.api[api.SetLastError] = func(c *cpu270) { gle = c.read(c.r[4] + 4); c.r[0] = 0xc0de; c.ret(4) }
			c.api[api.GetWindowPID] = func(c *cpu270) {
				if c.read(c.r[4]+4) != 0xabcd {
					t.Fatal("wrong HWND")
				}
				c.write(c.read(c.r[4]+8), tc.owner)
				c.r[0] = 1
				gle = 100
				c.ret(8)
			}
			c.api[api.OpenProcess] = func(c *cpu270) {
				openCalls++
				if c.read(c.r[4]+4) != 0x1000 || c.read(c.r[4]+8) != 0 || c.read(c.r[4]+12) != firstPID {
					t.Fatal("wrong query-only owner open")
				}
				c.r[0] = 0
				if tc.openOK {
					c.r[0] = 0xface
				}
				gle = 101
				c.ret(12)
			}
			c.api[api.GetTimes] = func(c *cpu270) {
				if c.read(c.r[4]+4) != 0xface {
					t.Fatal("wrong owner handle")
				}
				a := c.read(c.r[4] + 8)
				c.write(a, uint32(tc.birth))
				c.write(a+4, uint32(tc.birth>>32))
				c.r[0] = 0
				if tc.timesOK {
					c.r[0] = 1
				}
				gle = 102
				c.ret(20)
			}
			c.api[api.CloseHandle] = func(c *cpu270) {
				closeCalls++
				if c.read(c.r[4]+4) != 0xface {
					t.Fatal("closing wrong handle")
				}
				c.r[0] = 0
				if tc.closeOK {
					c.r[0] = 1
				}
				gle = 103
				c.ret(4)
			}
			c.run(t)
			want := uint32(0xabcd)
			if tc.hide {
				want = 0
			}
			if c.r[0] != want || gle != 92 || findCalls != 1 || c.r[4] != 0x800000 || c.r[3] != 0x4444 || c.r[5] != 0x5555 || c.r[6] != 0x6666 || c.r[7] != 0x7777 {
				t.Fatalf("stdcall/return/GLE contract: eax=%x gle=%d esp=%x", c.r[0], gle, c.r[4])
			}
			if openCalls > 0 && tc.openOK && closeCalls != 1 {
				t.Fatal("opened handle not closed")
			}
		})
	}
}

func TestMulti270ActualAssetGate(t *testing.T) {
	dir := os.Getenv("DNFBRIDGE_MULTI270_ASSET_DIRECTORY")
	if dir == "" {
		t.Skip("fixed current EXE/dstr asset directory not supplied")
	}
	for _, tc := range []struct {
		name string
		exe  bool
	}{{"DNF.exe", true}, {"dstr.dat", false}} {
		t.Run(tc.name, func(t *testing.T) {
			f, err := os.Open(filepath.Join(dir, tc.name))
			if err != nil {
				t.Fatal(err)
			}
			defer f.Close()
			s, err := f.Stat()
			if err != nil {
				t.Fatal(err)
			}
			if err = multi270CheckAsset(f, s.Size(), tc.exe); err != nil {
				t.Fatal(err)
			}
		})
	}
}
func TestMulti270PayloadRejectsIdentity(t *testing.T) {
	for _, pid := range []uint32{0, 2} {
		_, err := multi270Payload(0x10000, multi270APIs{1, 2, 3, 4, 5, 6, 7}, 8, pid, 1, 1, 2)
		if err == nil {
			t.Fatal("bad identity accepted")
		}
	}
}
func TestMulti270UnknownAssetFailsBeforeCreate(t *testing.T) {
	r := &zero270{}
	if err := multi270CheckAsset(r, 111763456, true); err == nil {
		t.Fatal("unknown EXE accepted")
	}
	if err := multi270CheckAsset(r, 1719808, false); err == nil {
		t.Fatal("unknown dstr accepted")
	}
}

type zero270 struct{}

func (*zero270) ReadAt(b []byte, _ int64) (int, error) { clear(b); return len(b), nil }

func TestMulti270GeneratedPayloadSizes(t *testing.T) {
	b, err := multi270Payload(0x100000, multi270APIs{1, 2, 3, 4, 5, 6, 7}, 8, 123, 1, 2, 456)
	if err != nil {
		t.Fatal(err)
	}
	if len(b) != 0x3000 {
		t.Fatal("wrong allocation size")
	}
	t.Log(fmt.Sprintf("actual mutex and window code are production-generated; allocation=%d", len(b)))
}

func TestMulti270GateTransaction(t *testing.T) {
	for _, fail := range []string{"install", "bind", "release", ""} {
		t.Run("fail_"+fail, func(t *testing.T) {
			var called []string
			step := func(name string) func() error {
				return func() error {
					called = append(called, name)
					if name == fail {
						return errors.New("fixed synthetic failure")
					}
					return nil
				}
			}
			err := multi270CommitGate(step("install"), step("bind"), step("release"))
			want := []string{"install", "bind", "release"}
			switch fail {
			case "install":
				want = want[:1]
			case "bind":
				want = want[:2]
			}
			if strings.Join(called, ",") != strings.Join(want, ",") || (err != nil) != (fail != "") {
				t.Fatalf("bad stopped-child transaction: %v %v", called, err)
			}
		})
	}
}

func TestMulti270PartialIATNeverReleases(t *testing.T) {
	for _, failSlot := range []uint32{multi270MutexSlot, multi270WindowSlot} {
		t.Run(fmt.Sprintf("slot_%x", failSlot), func(t *testing.T) {
			writes := 0
			bound, released := false, false
			err := multi270CommitGate(func() error {
				return multi270InstallPair(0x100000, func(addr uint32, b []byte) error {
					writes++
					if addr == multi270Base+failSlot {
						return errors.New("fixed partial-write failure")
					}
					return nil
				})
			}, func() error { bound = true; return nil }, func() error { released = true; return nil })
			if err == nil || bound || released || writes < 1 || writes > 2 {
				t.Fatal("partially installed child escaped gate")
			}
		})
	}
}

func TestMulti270AbortCannotResumeAlivePartialChild(t *testing.T) {
	for _, tc := range []struct{ term, exited, want bool }{{false, false, false}, {false, true, true}, {true, false, true}, {true, true, true}} {
		t.Run(fmt.Sprintf("terminated_%t_exited_%t", tc.term, tc.exited), func(t *testing.T) {
			if got := multi270MayContinueAbort(tc.term, tc.exited); got != tc.want {
				t.Fatal("alive partial child could be resumed")
			}
		})
	}
}

// This is a source-route RED/GREEN contract, not a claim that the old client was
// launched. The same test runs against exact archived baseline via a path input.
func TestMulti270ProductionRouteContract(t *testing.T) {
	p := os.Getenv("MULTI270_CONTROLLER_SOURCE")
	if p == "" {
		p = "controller.go"
	}
	b, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	s := string(b)
	start := strings.Index(s, "func (c *controller) startLocalClient(")
	if start < 0 {
		t.Fatal("real controller path missing")
	}
	end := strings.Index(s[start:], "func clientAccountURL(")
	if end < 0 {
		t.Fatal("controller boundary missing")
	}
	s = s[start : start+end]
	if !strings.Contains(s, "startClient270(ctx, cmd, multiInstance,") {
		t.Fatal("RED: real explicit-multi path has no owned-child compatibility adapter")
	}
	for _, required := range []string{"c.registerClientAccount(ctx, cfg, pid, accountID)", "time.NewTimer(5 * time.Second)", "captureClientStartFacts(cmd.Process)", "cmd.Process = process", "cmd.Process.Pid", "c.finishStartedClient270(ctx, cmd, multiInstance, executable)"} {
		if !strings.Contains(s, required) {
			t.Fatalf("normal contract lost: %s", required)
		}
	}
}

func TestMulti270OnlyInitialOwnedNTDLLBreakpointIsHandled(t *testing.T) {
	cases := []struct {
		name                                    string
		code, address, base, size, tid, primary uint32
		seen, want                              bool
	}{
		{"initial", 0x80000003, 0x70000100, 0x70000000, 0x2000, 1, 1, false, true},
		{"othermodule", 0x80000003, 0x60000100, 0x70000000, 0x2000, 1, 1, false, false},
		{"otherthread", 0x80000003, 0x70000100, 0x70000000, 0x2000, 2, 1, false, false},
		{"alreadyhandled", 0x80000003, 0x70000100, 0x70000000, 0x2000, 1, 1, true, false},
		{"unknownmodule", 0x80000003, 0x70000100, 0, 0, 1, 1, false, false},
		{"otherexception", 0xc0000005, 0x70000100, 0x70000000, 0x2000, 1, 1, false, false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := multi270LoaderBreakpoint(c.code, c.address, c.base, c.size, c.tid, c.primary, c.seen); got != c.want {
				t.Fatal("foreign/unrelated exception consumed")
			}
		})
	}
}
